import{_ as i,a0 as l,w as p,s as g,ao as a,I as n,x as t,a1 as e,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse(`{"title":"在 Linux 中使用 avconv 工具录制计算机桌面视频和音频 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中使用 avconv 工具录制计算机桌面视频和音频 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中使用 avconv 工具录制计算机桌面视频和音频 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中使用 avconv 工具录制计算机桌面视频和音频 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141108 How to Record Your Desktop Video and Audio Using 'Avconv' Tool in Ubuntu","title":"在 Linux 中使用 avconv 工具录制计算机桌面视频和音频","tag":"201411","desc":""},"relativePath":"201411/20141108 How to Record Your Desktop Video and Audio Using 'Avconv' Tool in Ubuntu.md","filePath":"[post].md"}`),u={name:"201411/20141108 How to Record Your Desktop Video and Audio Using 'Avconv' Tool in Ubuntu.md"};function d(v,o,m,c,w,b){const r=l("Link");return p(),g("div",null,[o[19]||(o[19]=a(`<h1 id="在-linux-中使用-avconv-工具录制计算机桌面视频和音频" tabindex="-1">在 Linux 中使用&quot;avconv&quot;工具录制计算机桌面视频和音频 <a class="header-anchor" href="#在-linux-中使用-avconv-工具录制计算机桌面视频和音频" aria-label="Permalink to “在 Linux 中使用avconv工具录制计算机桌面视频和音频”">​</a></h1><p><strong>Libav</strong>是一款跨平台的工具库，能够用来处理多媒体文件、流和协议。它最初是源自ffmpeg。Libav带有一些工具，比如：</p><ul><li><strong>Avplay</strong>： 一款视频音频播放器。</li><li><strong>Avconv</strong>： 能够记录多个设备输入源的一个多媒体转换器和视频音频录制器。</li><li><strong>Avprobe</strong>： 一个连接多媒体文件流并且返回关于这个文件流的统计信息的工具。</li><li><strong>Libavfilter</strong>： 一个Libav工具的过滤器(filtering)API。</li></ul><p>在这篇文章里面，我们就要展示如何通过&#39;Avconv&#39;程序在<strong>Debian/Ubuntu/Linux Mint</strong>发行版上录制Linux桌面视频音频。</p><h3 id="第一步-下载-avconv-工具" tabindex="-1">第一步：下载 Avconv 工具 <a class="header-anchor" href="#第一步-下载-avconv-工具" aria-label="Permalink to “第一步：下载 Avconv 工具”">​</a></h3><p><strong>1.</strong> <strong>avconv</strong>是 “<strong>libav-tools</strong>” 的一部分， 可以通过官方的基于debian的仓库下载，比如Mint、Ubuntu。输入下面命令即可：</p><pre><code>$ sudo apt-get update
$ sudo apt-get install libav-tools
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Install-avconv-tool.jpeg" alt="Install Avconv Tool"></p><p><em>下载Avconv工具</em></p><p><strong>注意</strong>： 如果从默认仓库下载的话， ‘<strong>avconv</strong>’ 的版本可能比较老。 因此我们推荐你拉取最新的git官方版本。</p><pre><code>$ sudo apt-get install yasm
$ git clone git://git.libav.org/libav.git
$ cd libav
$ ./configure
$ make
$ sudo make install
</code></pre><p><strong>注意</strong>： 你应该运行 ‘<strong>./configure –help</strong>’ 来列出所有的可选配置选项并且安装相应的解码器和库，你还需要做很多工作来解决依赖问题。</p><p>也要注意，如果你是从源代码编译的，就需要使用<strong>sudo avconv</strong>而不是<strong>avconv</strong>来运行这个工具。</p><h3 id="第二步-开始录制桌面视频" tabindex="-1">第二步：开始录制桌面视频 <a class="header-anchor" href="#第二步-开始录制桌面视频" aria-label="Permalink to “第二步：开始录制桌面视频”">​</a></h3><p><strong>2.</strong>一切就绪，现在可以通过运行下面的命令录制你的视频了：</p><pre><code>$ avconv -f x11grab -r 25 -s 1920x1080 -i :0.0 -vcodec libx264 -threads 4 $HOME/output.avi
</code></pre><p>简单解释一下这个命令:</p><ul><li><strong>avconv -f x11grab</strong> 默认从X服务捕捉画面。</li><li><strong>-r 25</strong> 这是你需要的视频帧率，可以自行设置。</li><li><strong>-s 1920×1080</strong> 是你的系统的桌面分辨率，要设置成你当前桌面的分辨率，这一点非常重要。</li><li><strong>-i :0.0</strong> 我们要记录的位置（X 服务输出端口），设置成这样就可以了。</li><li><strong>-vcodec libx264</strong> 我们用来录制视频的编码器。</li><li><strong>-threads 4</strong> 线程数，可以根据情况更改。</li><li><strong>$HOME/output</strong> 输出的目标文件路径。</li><li><strong>.avi</strong> 使用的视频格式，可以换成 “flv”、“mp4″、 “wmv”、 “mov”、 “mkv”等。</li></ul><p><strong>3.</strong>在运行命令之后，就会在terminal上自动运行一个进程进行记录，按&quot;Ctrl+C&quot;键来终止记录。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Record-Desktop-Screen.jpeg" alt="Record Desktop Screen"></p><p><em>录制桌面视频</em></p><p><strong>4.</strong> 现在，你可以使用VLC或者其他的播放器，或者使用来自Libav包里的播放器&quot;avplay&quot;来播放你录制的视频。</p><pre><code>$ avplay $HOME/output.avi
</code></pre><p><strong>注意:</strong> 别忘了替换输出文件的路径为你自己的，录制效果还是很好的。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Play-Recorded-Video.jpeg" alt="Play Recorded Video"></p><p><em>播放录制的文件</em></p>`,26)),n("p",null,[o[1]||(o[1]=t("这有一段我用 “",-1)),o[2]||(o[2]=n("strong",null,"avconv",-1)),o[3]||(o[3]=t("” 录制的",-1)),e(r,{href:"http://www.youtube.com/embed/g1FEh4wByGE"},{default:s(()=>[...o[0]||(o[0]=[t("视频",-1)])]),_:1}),o[4]||(o[4]=t(" （墙外）。",-1))]),o[20]||(o[20]=a(`<h3 id="第三步-开始录制桌面的音频和视频" tabindex="-1">第三步： 开始录制桌面的音频和视频 <a class="header-anchor" href="#第三步-开始录制桌面的音频和视频" aria-label="Permalink to “第三步： 开始录制桌面的音频和视频”">​</a></h3><p><strong>5.</strong> 如果也想同时录制音频，先运行这个命令，列出所有的音频输入源：</p><pre><code>$ arecord -l
</code></pre><p>结果类似这样：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Audio-Input.png" alt="Check Audio Input"></p><p><em>检查音频输入源</em></p><p>在我这里，我只有一个音频输入源，所以数量是<strong>1</strong>，这就是我使用如下命令来捕捉我的视频以及麦克风的音频的原因。</p><pre><code>$ avconv -f alsa -i hw:1 -f x11grab -r 25 -s 1920x1080 -i :0.0 -vcodec libx264 -threads 4 output-file2.avi
</code></pre><p>我修改了部分地方，下面做个简短的解释：</p><ul><li><strong>-f</strong> alsa 一个从alsa设备捕捉声音的选项。</li><li><strong>-i</strong> hw:1 是一个从 “hw:1” 设备捕捉音频的选项，这个设备是我电脑上仅有的一个音频输入设备。</li></ul><p><strong>注意</strong>: 如果你想用<strong>arecord -l</strong>显示的<strong>1</strong>之外的设备的话，别忘了替换 “<strong>1</strong>”。</p><p>结束录制，再来一次“<strong>Ctrl + C</strong>” 就可以。</p><h3 id="第四步-开始录制桌面音频" tabindex="-1">第四步： 开始录制桌面音频 <a class="header-anchor" href="#第四步-开始录制桌面音频" aria-label="Permalink to “第四步： 开始录制桌面音频”">​</a></h3><p><strong>6.</strong> 如果只想录制音频的话，使用下面的命令。</p><pre><code>$ avconv -f alsa -i hw:1 out.wav
</code></pre><p><strong>7.</strong> 替换成 <strong>.mp3</strong> 等Libav支持的格式都可以，播放 <strong>out.wav</strong>就能听到你自己的声音了。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Record-Desktop-Audio.png" alt="Record Desktop Audio"></p><p><em>录制桌面音频</em></p><p>###最后 ###</p><p>“<strong>avconv</strong>” 工具可以用来做很多其他事情，不仅仅是录制桌面视频，更多的教程和文档请移步到官网。</p>`,20)),n("ul",null,[n("li",null,[e(r,{href:"https://libav.org/avconv.html"},{default:s(()=>[...o[5]||(o[5]=[t("https://libav.org/avconv.html",-1)])]),_:1})])]),o[21]||(o[21]=n("p",null,'你对"avconv"的体验如何，你使用过其他工具录制桌面视频么？在评论里面和我们分享吧。',-1)),o[22]||(o[22]=n("hr",null,null,-1)),n("p",null,[o[7]||(o[7]=t("via: ",-1)),e(r,{href:"http://www.tecmint.com/record-ubuntu-desktop-screen-using-avconv/"},{default:s(()=>[...o[6]||(o[6]=[t("http://www.tecmint.com/record-ubuntu-desktop-screen-using-avconv/",-1)])]),_:1})]),n("p",null,[o[11]||(o[11]=t("作者：",-1)),e(r,{href:"http://www.tecmint.com/author/hannyhelal/"},{default:s(()=>[...o[8]||(o[8]=[t("Hanny Helal",-1)])]),_:1}),o[12]||(o[12]=t(" 译者：",-1)),e(r,{href:"https://github.com/ggaaooppeenngg"},{default:s(()=>[...o[9]||(o[9]=[t("ggaaooppeenngg",-1)])]),_:1}),o[13]||(o[13]=t(" 校对：",-1)),e(r,{href:"https://github.com/wxy"},{default:s(()=>[...o[10]||(o[10]=[t("wxy",-1)])]),_:1})]),n("p",null,[o[16]||(o[16]=t("本文由 ",-1)),e(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...o[14]||(o[14]=[t("LCTT",-1)])]),_:1}),o[17]||(o[17]=t(" 原创翻译，",-1)),e(r,{href:"http://linux.cn/"},{default:s(()=>[...o[15]||(o[15]=[t("Linux中国",-1)])]),_:1}),o[18]||(o[18]=t(" 荣誉推出",-1))])])}const h=i(u,[["render",d]]);export{T as __pageData,h as default};
